package main

import (
	"bufio"
	"bytes"
	"fmt"
	"math"
	"math/big"
	"os"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

const (
	appDescription = "Find the password of protected ZIP files"
	appVersion     = "zip-password-finder 0.10.3"
	helpText       = `Find the password of protected ZIP files

Usage: executable [OPTIONS] --inputFile <inputFile>

Options:
  -i, --inputFile <inputFile>                    path to zip input file
  -w, --workers <workers>                        number of workers
  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file
  -c, --charset <charset>                        charset to use to generate password [default: lud]
      --charsetFile <charsetFile>                path to a charset file
      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]
      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
  -s, --startingPassword <startingPassword>      password to start from
  -h, --help                                     Print help
  -V, --version                                  Print version
`
)

var (
	defaultCharsetSpec = "lud"
	optionDisplays     = map[string]string{
		"inputFile":          "--inputFile <inputFile>",
		"workers":            "--workers <workers>",
		"passwordDictionary": "--passwordDictionary <passwordDictionary>",
		"charset":            "--charset <charset>",
		"charsetFile":        "--charsetFile <charsetFile>",
		"minPasswordLen":     "--minPasswordLen <minPasswordLen>",
		"maxPasswordLen":     "--maxPasswordLen <maxPasswordLen>",
		"fileNumber":         "--fileNumber <fileNumber>",
		"startingPassword":   "--startingPassword <startingPassword>",
	}
	charsetClasses = map[byte][]byte{
		'l': []byte("abcdefghijklmnopqrstuvwxyz"),
		'u': []byte("ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
		'd': []byte("0123456789"),
		'h': []byte("0123456789abcdef"),
		'H': []byte("0123456789ABCDEF"),
		's': []byte(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"),
	}
)

type cliMode int

const (
	cliModeRun cliMode = iota
	cliModeHelp
	cliModeVersion
)

type cliError struct {
	exitCode int
	message  string
}

type config struct {
	inputFile          string
	workers            int
	passwordDictionary string
	charsetSpec        string
	charsetFile        string
	minPasswordLen     int
	maxPasswordLen     int
	fileNumber         int
	startingPassword   string
}

type runConfig struct {
	cfg     config
	dict    [][]byte
	charset []byte
}

func main() {
	cfg, mode, err := parseArgs(os.Args[1:])
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	switch mode {
	case cliModeHelp:
		writeStdout(helpText)
		return
	case cliModeVersion:
		writeStdout(appVersion + "\n")
		return
	}

	runCfg, err := validateRunConfig(cfg)
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	target, err := loadEncryptedTarget(runCfg.cfg.inputFile, runCfg.cfg.fileNumber)
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	tty := isTTY(os.Stdout)
	if tty {
		printTTYPrelude(target, runCfg)
	}

	start := time.Now()
	var found bool
	var password []byte
	if len(runCfg.dict) > 0 {
		found, password = searchDictionary(target, runCfg.dict, runCfg.cfg.workers)
	} else {
		found, password = searchBruteForce(
			target,
			runCfg.charset,
			runCfg.cfg.minPasswordLen,
			runCfg.cfg.maxPasswordLen,
			[]byte(runCfg.cfg.startingPassword),
			runCfg.cfg.workers,
		)
	}

	writeStdout("Time elapsed: " + formatDuration(time.Since(start)) + "\n")
	if found {
		writeStdout("Password found:" + string(password) + "\n")
		return
	}
	writeStdout("Password not found\n")
}

func parseArgs(args []string) (config, cliMode, *cliError) {
	cfg := config{
		workers:        defaultWorkers(),
		charsetSpec:    defaultCharsetSpec,
		minPasswordLen: 1,
		maxPasswordLen: 10,
		fileNumber:     0,
	}
	seen := map[string]bool{}
	seenOrder := make([]string, 0, len(optionDisplays))

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if strings.HasPrefix(arg, "--") {
			name, value, hasInlineValue := splitLongOption(arg)
			switch name {
			case "--help":
				return cfg, cliModeHelp, nil
			case "--version":
				return cfg, cliModeVersion, nil
			case "--inputFile":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "inputFile"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				cfg.inputFile = v
			case "--workers":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "workers"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				parsed, parseErr := parseUintArg(v)
				if parseErr != "" {
					return cfg, cliModeRun, invalidValueError(v, optionDisplays["workers"], parseErr)
				}
				cfg.workers = int(parsed)
			case "--passwordDictionary":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "passwordDictionary"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				cfg.passwordDictionary = v
			case "--charset":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "charset"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				cfg.charsetSpec = v
			case "--charsetFile":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "charsetFile"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				cfg.charsetFile = v
			case "--minPasswordLen":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "minPasswordLen"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				parsed, parseErr := parseUintArg(v)
				if parseErr != "" {
					return cfg, cliModeRun, invalidValueError(v, optionDisplays["minPasswordLen"], parseErr)
				}
				cfg.minPasswordLen = int(parsed)
			case "--maxPasswordLen":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "maxPasswordLen"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				parsed, parseErr := parseUintArg(v)
				if parseErr != "" {
					return cfg, cliModeRun, invalidValueError(v, optionDisplays["maxPasswordLen"], parseErr)
				}
				cfg.maxPasswordLen = int(parsed)
			case "--fileNumber":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "fileNumber"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				parsed, parseErr := parseUintArg(v)
				if parseErr != "" {
					return cfg, cliModeRun, invalidValueError(v, optionDisplays["fileNumber"], parseErr)
				}
				cfg.fileNumber = int(parsed)
			case "--startingPassword":
				v, cliErr := longOptionValue(args, &i, name, value, hasInlineValue)
				if cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				if cliErr := markSeen(seen, &seenOrder, "startingPassword"); cliErr != nil {
					return cfg, cliModeRun, cliErr
				}
				cfg.startingPassword = v
			default:
				return cfg, cliModeRun, unexpectedArgumentError(name)
			}
			continue
		}

		if strings.HasPrefix(arg, "-") && arg != "-" {
			cluster := arg[1:]
			for j := 0; j < len(cluster); j++ {
				switch cluster[j] {
				case 'h':
					return cfg, cliModeHelp, nil
				case 'V':
					return cfg, cliModeVersion, nil
				case 'i':
					v, cliErr := shortOptionValue(args, &i, cluster, &j, 'i')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					if cliErr := markSeen(seen, &seenOrder, "inputFile"); cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					cfg.inputFile = v
				case 'w':
					v, cliErr := shortOptionValue(args, &i, cluster, &j, 'w')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					if cliErr := markSeen(seen, &seenOrder, "workers"); cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					parsed, parseErr := parseUintArg(v)
					if parseErr != "" {
						return cfg, cliModeRun, invalidValueError(v, optionDisplays["workers"], parseErr)
					}
					cfg.workers = int(parsed)
				case 'p':
					v, cliErr := shortOptionValue(args, &i, cluster, &j, 'p')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					if cliErr := markSeen(seen, &seenOrder, "passwordDictionary"); cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					cfg.passwordDictionary = v
				case 'c':
					v, cliErr := shortOptionValue(args, &i, cluster, &j, 'c')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					if cliErr := markSeen(seen, &seenOrder, "charset"); cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					cfg.charsetSpec = v
				case 's':
					v, cliErr := shortOptionValue(args, &i, cluster, &j, 's')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					if cliErr := markSeen(seen, &seenOrder, "startingPassword"); cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					cfg.startingPassword = v
				default:
					return cfg, cliModeRun, unexpectedArgumentError("-"+string(cluster[j]))
				}
			}
			continue
		}

		return cfg, cliModeRun, unexpectedArgumentError(arg)
	}

	if cfg.inputFile == "" {
		return cfg, cliModeRun, missingRequiredError(seenOrder)
	}

	return cfg, cliModeRun, nil
}

func validateRunConfig(cfg config) (runConfig, *cliError) {
	if !pathExists(cfg.inputFile) {
		return runConfig{}, runtimeArgError("'inputFile' does not exist")
	}
	if cfg.passwordDictionary != "" && !pathExists(cfg.passwordDictionary) {
		return runConfig{}, runtimeArgError("'passwordDictionary' does not exist")
	}
	if cfg.charsetFile != "" && !pathExists(cfg.charsetFile) {
		return runConfig{}, runtimeArgError("'charsetFile' does not exist")
	}
	if cfg.workers <= 0 {
		return runConfig{}, runtimeArgError("'workers' must be positive")
	}
	if cfg.maxPasswordLen < cfg.minPasswordLen {
		return runConfig{}, runtimeArgError("'maxPasswordLen' must be equal or greater than 'minPasswordLen'")
	}
	if cfg.passwordDictionary != "" && cfg.startingPassword != "" {
		return runConfig{}, runtimeArgError("'startingPassword' cannot be used with a dictionary file")
	}

	runCfg := runConfig{cfg: cfg}
	if cfg.passwordDictionary != "" {
		dict, err := loadDictionary(cfg.passwordDictionary)
		if err != nil {
			return runConfig{}, err
		}
		runCfg.dict = dict
		return runCfg, nil
	}

	var charset []byte
	var err *cliError
	if cfg.charsetFile != "" {
		charset, err = loadCharsetFile(cfg.charsetFile)
	} else {
		charset, err = buildCharsetFromSpec(cfg.charsetSpec)
	}
	if err != nil {
		return runConfig{}, err
	}

	if cfg.startingPassword != "" {
		passwordBytes := []byte(cfg.startingPassword)
		if len(passwordBytes) < cfg.minPasswordLen || len(passwordBytes) > cfg.maxPasswordLen {
			return runConfig{}, runtimeArgError("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration")
		}
		if !charsetContainsAll(charset, passwordBytes) {
			return runConfig{}, runtimeArgError("'startingPassword' uses characters out of the generation charset")
		}
	}

	runCfg.charset = charset
	return runCfg, nil
}

func loadDictionary(path string) ([][]byte, *cliError) {
	file, err := os.Open(path)
	if err != nil {
		return nil, runtimeArgError("'passwordDictionary' does not exist")
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	passwords := make([][]byte, 0)
	for scanner.Scan() {
		line := append([]byte(nil), scanner.Bytes()...)
		passwords = append(passwords, line)
	}
	if err := scanner.Err(); err != nil {
		return nil, &cliError{exitCode: 1, message: "Dictionary file error - " + err.Error() + "\n"}
	}
	return passwords, nil
}

func loadCharsetFile(path string) ([]byte, *cliError) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, runtimeArgError("'charsetFile' does not exist")
	}
	return uniqueSortedBytes(data), nil
}

func buildCharsetFromSpec(spec string) ([]byte, *cliError) {
	set := make([]byte, 0, 64)
	for i := 0; i < len(spec); i++ {
		chars, ok := charsetClasses[spec[i]]
		if !ok {
			return nil, runtimeQuotedError(fmt.Sprintf("Unknown charset option '%c'", spec[i]))
		}
		set = append(set, chars...)
	}
	return uniqueSortedBytes(set), nil
}

func charsetContainsAll(charset, value []byte) bool {
	if len(value) == 0 {
		return true
	}
	var table [256]bool
	for _, b := range charset {
		table[b] = true
	}
	for _, b := range value {
		if !table[b] {
			return false
		}
	}
	return true
}

func uniqueSortedBytes(src []byte) []byte {
	if len(src) == 0 {
		return nil
	}
	seen := [256]bool{}
	dst := make([]byte, 0, len(src))
	for _, b := range src {
		if !seen[b] {
			seen[b] = true
			dst = append(dst, b)
		}
	}
	sort.Slice(dst, func(i, j int) bool { return dst[i] < dst[j] })
	return dst
}

func searchDictionary(target *encryptedTarget, dict [][]byte, workers int) (bool, []byte) {
	if len(dict) == 0 {
		return false, nil
	}

	var (
		found  atomic.Bool
		result atomic.Value
		wg     sync.WaitGroup
	)

	for worker := 0; worker < workers; worker++ {
		start := len(dict) * worker / workers
		end := len(dict) * (worker + 1) / workers
		if start >= end {
			continue
		}
		wg.Add(1)
		go func(start, end int) {
			defer wg.Done()
			for i := start; i < end; i++ {
				if found.Load() {
					return
				}
				if target.testPassword(dict[i]) {
					if !found.Swap(true) {
						result.Store(append([]byte(nil), dict[i]...))
					}
					return
				}
			}
		}(start, end)
	}

	wg.Wait()
	if !found.Load() {
		return false, nil
	}
	return true, result.Load().([]byte)
}

func searchBruteForce(target *encryptedTarget, charset []byte, minLen, maxLen int, startingPassword []byte, workers int) (bool, []byte) {
	if len(charset) == 0 {
		return false, nil
	}

	indexMap := make(map[byte]int, len(charset))
	for i, b := range charset {
		indexMap[b] = i
	}

	var (
		found  atomic.Bool
		result atomic.Value
	)

	for length := minLen; length <= maxLen && !found.Load(); length++ {
		if len(startingPassword) > 0 && length < len(startingPassword) {
			continue
		}

		total, ok := powUint64(uint64(len(charset)), length)
		if !ok {
			total = math.MaxUint64
		}

		startIndex := uint64(0)
		if len(startingPassword) > 0 && length == len(startingPassword) {
			startIndex = passwordIndex(startingPassword, indexMap, len(charset))
		}
		if startIndex >= total {
			continue
		}

		remaining := total - startIndex
		if remaining == 0 {
			continue
		}

		var wg sync.WaitGroup
		for worker := 0; worker < workers; worker++ {
			begin := startIndex + remaining*uint64(worker)/uint64(workers)
			end := startIndex + remaining*uint64(worker+1)/uint64(workers)
			if begin >= end {
				continue
			}
			wg.Add(1)
			go func(length int, begin, end uint64) {
				defer wg.Done()
				digits := indexToDigits(begin, length, len(charset))
				candidate := digitsToPassword(digits, charset)
				for current := begin; current < end; current++ {
					if found.Load() {
						return
					}
					if target.testPassword(candidate) {
						if !found.Swap(true) {
							result.Store(append([]byte(nil), candidate...))
						}
						return
					}
					if current+1 >= end {
						return
					}
					incrementPassword(digits, candidate, charset)
				}
			}(length, begin, end)
		}
		wg.Wait()
	}

	if !found.Load() {
		return false, nil
	}
	return true, result.Load().([]byte)
}

func passwordIndex(password []byte, indexMap map[byte]int, base int) uint64 {
	var idx uint64
	for _, b := range password {
		idx = idx*uint64(base) + uint64(indexMap[b])
	}
	return idx
}

func indexToDigits(index uint64, length, base int) []int {
	digits := make([]int, length)
	for i := length - 1; i >= 0; i-- {
		digits[i] = int(index % uint64(base))
		index /= uint64(base)
	}
	return digits
}

func digitsToPassword(digits []int, charset []byte) []byte {
	password := make([]byte, len(digits))
	for i, digit := range digits {
		password[i] = charset[digit]
	}
	return password
}

func incrementPassword(digits []int, password, charset []byte) {
	for i := len(digits) - 1; i >= 0; i-- {
		digits[i]++
		if digits[i] < len(charset) {
			password[i] = charset[digits[i]]
			for j := i + 1; j < len(digits); j++ {
				digits[j] = 0
				password[j] = charset[0]
			}
			return
		}
		digits[i] = 0
		password[i] = charset[0]
	}
}

func powUint64(base uint64, exp int) (uint64, bool) {
	if exp == 0 {
		return 1, true
	}
	value := uint64(1)
	for i := 0; i < exp; i++ {
		if base != 0 && value > math.MaxUint64/base {
			return 0, false
		}
		value *= base
	}
	return value, true
}

func printTTYPrelude(target *encryptedTarget, runCfg runConfig) {
	writeStdout(fmt.Sprintf("Targeting file '%s' within the archive\n", target.name))
	switch target.encryption {
	case encryptionZipCrypto:
		writeStdout("Archive encrypted with ZipCrypto - expect a much faster throughput\n")
	case encryptionAES:
		writeStdout(fmt.Sprintf("Archive encrypted with %s - expect a long wait time\n", target.aes.label))
	}
	if len(runCfg.dict) > 0 {
		writeStdout(fmt.Sprintf("Using passwords dictionary %q with %d candidates.\n", runCfg.cfg.passwordDictionary, len(runCfg.dict)))
	}
	writeStdout(fmt.Sprintf("Starting %d workers to test passwords\n", runCfg.cfg.workers))
	if len(runCfg.dict) == 0 {
		if runCfg.cfg.startingPassword != "" {
			writeStdout(fmt.Sprintf(
				"Generating passwords with length from %d to %d starting from %s for charset with length %d\n",
				runCfg.cfg.minPasswordLen,
				runCfg.cfg.maxPasswordLen,
				runCfg.cfg.startingPassword,
				len(runCfg.charset),
			))
		} else {
			writeStdout(fmt.Sprintf(
				"Generating passwords with length from %d to %d for charset with length %d\n",
				runCfg.cfg.minPasswordLen,
				runCfg.cfg.maxPasswordLen,
				len(runCfg.charset),
			))
		}
		if len(runCfg.charset) > 0 {
			writeStdout(string(runCfg.charset) + "\n")
		}
	}
}

func parseUintArg(value string) (uint64, string) {
	if value == "" {
		return 0, "cannot parse integer from empty string"
	}
	for i := 0; i < len(value); i++ {
		if value[i] < '0' || value[i] > '9' {
			return 0, "invalid digit found in string"
		}
	}
	n := new(big.Int)
	if _, ok := n.SetString(value, 10); !ok {
		return 0, "invalid digit found in string"
	}
	if n.BitLen() > 64 {
		return 0, "number too large to fit in target type"
	}
	return n.Uint64(), ""
}

func splitLongOption(arg string) (string, string, bool) {
	if idx := strings.IndexByte(arg, '='); idx >= 0 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func longOptionValue(args []string, index *int, name, inlineValue string, hasInlineValue bool) (string, *cliError) {
	if hasInlineValue {
		return inlineValue, nil
	}
	if *index+1 >= len(args) {
		return "", missingValueError(optionDisplays[canonicalNameForLong(name)])
	}
	next := args[*index+1]
	if strings.HasPrefix(next, "-") && next != "-" {
		if isKnownOptionToken(next) {
			return "", missingValueError(optionDisplays[canonicalNameForLong(name)])
		}
		return "", unexpectedArgumentError(next)
	}
	*index++
	return next, nil
}

func shortOptionValue(args []string, index *int, cluster string, clusterIndex *int, short byte) (string, *cliError) {
	if *clusterIndex+1 < len(cluster) {
		value := cluster[*clusterIndex+1:]
		*clusterIndex = len(cluster)
		return value, nil
	}
	if *index+1 >= len(args) {
		return "", missingValueError(optionDisplays[canonicalNameForShort(short)])
	}
	next := args[*index+1]
	if strings.HasPrefix(next, "-") && next != "-" {
		if isKnownOptionToken(next) {
			return "", missingValueError(optionDisplays[canonicalNameForShort(short)])
		}
		return "", unexpectedArgumentError(next)
	}
	*index++
	*clusterIndex = len(cluster)
	return next, nil
}

func isKnownOptionToken(token string) bool {
	if token == "" {
		return false
	}
	if strings.HasPrefix(token, "--") {
		name, _, _ := splitLongOption(token)
		switch name {
		case "--inputFile", "--workers", "--passwordDictionary", "--charset", "--charsetFile", "--minPasswordLen", "--maxPasswordLen", "--fileNumber", "--startingPassword", "--help", "--version":
			return true
		default:
			return false
		}
	}
	if strings.HasPrefix(token, "-") && token != "-" {
		switch token[1] {
		case 'i', 'w', 'p', 'c', 's', 'h', 'V':
			return true
		default:
			return false
		}
	}
	return false
}

func markSeen(seen map[string]bool, order *[]string, canonical string) *cliError {
	if seen[canonical] {
		return duplicateArgumentError(optionDisplays[canonical])
	}
	seen[canonical] = true
	*order = append(*order, canonical)
	return nil
}

func canonicalNameForLong(name string) string {
	switch name {
	case "--inputFile":
		return "inputFile"
	case "--workers":
		return "workers"
	case "--passwordDictionary":
		return "passwordDictionary"
	case "--charset":
		return "charset"
	case "--charsetFile":
		return "charsetFile"
	case "--minPasswordLen":
		return "minPasswordLen"
	case "--maxPasswordLen":
		return "maxPasswordLen"
	case "--fileNumber":
		return "fileNumber"
	case "--startingPassword":
		return "startingPassword"
	default:
		return ""
	}
}

func canonicalNameForShort(short byte) string {
	switch short {
	case 'i':
		return "inputFile"
	case 'w':
		return "workers"
	case 'p':
		return "passwordDictionary"
	case 'c':
		return "charset"
	case 's':
		return "startingPassword"
	default:
		return ""
	}
}

func missingRequiredError(seenOrder []string) *cliError {
	usageParts := []string{"Usage: executable --inputFile <inputFile>"}
	for _, item := range seenOrder {
		if item == "inputFile" {
			continue
		}
		usageParts = append(usageParts, optionDisplays[item])
	}
	return &cliError{
		exitCode: 2,
		message: "error: the following required arguments were not provided:\n" +
			"  --inputFile <inputFile>\n\n" +
			strings.Join(usageParts, " ") + "\n\n" +
			"For more information, try '--help'.\n",
	}
}

func missingValueError(display string) *cliError {
	return &cliError{
		exitCode: 2,
		message: fmt.Sprintf(
			"error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n",
			display,
		),
	}
}

func invalidValueError(value, display, parseErr string) *cliError {
	return &cliError{
		exitCode: 2,
		message: fmt.Sprintf(
			"error: invalid value '%s' for '%s': %s\n\nFor more information, try '--help'.\n",
			value,
			display,
			parseErr,
		),
	}
}

func duplicateArgumentError(display string) *cliError {
	return &cliError{
		exitCode: 2,
		message: fmt.Sprintf(
			"error: the argument '%s' cannot be used multiple times\n\nUsage: executable [OPTIONS] --inputFile <inputFile>\n\nFor more information, try '--help'.\n",
			display,
		),
	}
}

func unexpectedArgumentError(value string) *cliError {
	return &cliError{
		exitCode: 2,
		message: fmt.Sprintf(
			"error: unexpected argument '%s' found\n\nUsage: executable [OPTIONS] --inputFile <inputFile>\n\nFor more information, try '--help'.\n",
			value,
		),
	}
}

func runtimeArgError(message string) *cliError {
	return &cliError{
		exitCode: 1,
		message: fmt.Sprintf("CLI argument error - %q\n", message),
	}
}

func runtimeQuotedError(message string) *cliError {
	return &cliError{
		exitCode: 1,
		message: fmt.Sprintf("CLI argument error - %q\n", message),
	}
}

func defaultWorkers() int {
	if cores := linuxPhysicalCores(); cores > 0 {
		return cores
	}
	cpus := runtime.NumCPU()
	if cpus <= 1 {
		return 1
	}
	return cpus / 2
}

func linuxPhysicalCores() int {
	if runtime.GOOS != "linux" {
		return 0
	}
	data, err := os.ReadFile("/proc/cpuinfo")
	if err != nil {
		return 0
	}

	entries := strings.Split(string(data), "\n\n")
	pairs := map[string]struct{}{}
	coreOnly := map[string]struct{}{}
	for _, entry := range entries {
		if strings.TrimSpace(entry) == "" {
			continue
		}
		var physicalID, coreID string
		lines := strings.Split(entry, "\n")
		for _, line := range lines {
			parts := strings.SplitN(line, ":", 2)
			if len(parts) != 2 {
				continue
			}
			key := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			switch key {
			case "physical id":
				physicalID = value
			case "core id":
				coreID = value
			}
		}
		if physicalID != "" && coreID != "" {
			pairs[physicalID+"/"+coreID] = struct{}{}
		} else if coreID != "" {
			coreOnly[coreID] = struct{}{}
		}
	}
	if len(pairs) > 0 {
		return len(pairs)
	}
	if len(coreOnly) > 0 {
		return len(coreOnly)
	}
	return 0
}

func formatDuration(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	if d == 0 {
		return "0ns"
	}

	type unit struct {
		size time.Duration
		name string
	}
	units := []unit{
		{24 * time.Hour, "d"},
		{time.Hour, "h"},
		{time.Minute, "m"},
		{time.Second, "s"},
		{time.Millisecond, "ms"},
		{time.Microsecond, "us"},
		{time.Nanosecond, "ns"},
	}

	parts := make([]string, 0, 4)
	for _, unit := range units {
		if d < unit.size {
			continue
		}
		value := d / unit.size
		d -= value * unit.size
		parts = append(parts, strconv.FormatInt(int64(value), 10)+unit.name)
	}
	if len(parts) == 0 {
		return "0ns"
	}
	return strings.Join(parts, " ")
}

func pathExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func writeStdout(message string) {
	_, _ = os.Stdout.WriteString(message)
}

func writeStderr(message string) {
	_, _ = os.Stderr.WriteString(message)
}

func isTTY(file *os.File) bool {
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

