package main

import (
	"archive/zip"
	"bytes"
	"compress/flate"
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/sha1"
	"encoding/binary"
	"fmt"
	"hash/crc32"
	"io"
	"os"
)

type encryptionKind int

const (
	encryptionZipCrypto encryptionKind = iota
	encryptionAES
)

type aesInfo struct {
	strength    byte
	keyLength   int
	saltLength  int
	actualMethod uint16
	version     uint16
	label       string
}

type encryptedTarget struct {
	name             string
	encryption       encryptionKind
	method           uint16
	flags            uint16
	modifiedTime     uint16
	uncompressedSize uint64
	crc32            uint32
	rawData          []byte
	aes              *aesInfo
}

func loadEncryptedTarget(path string, fileNumber int) (*encryptedTarget, *cliError) {
	reader, err := openZipReader(path)
	if err != nil {
		return nil, &cliError{exitCode: 1, message: "Invalid zip file error - " + err.Error() + "\n"}
	}
	defer reader.Close()

	if fileNumber < 0 || fileNumber >= len(reader.File) {
		return nil, &cliError{
			exitCode: 1,
			message:  fmt.Sprintf("File number not found within archive error - '%d'\n", fileNumber),
		}
	}

	file := reader.File[fileNumber]
	if file.Flags&0x1 == 0 {
		return nil, &cliError{
			exitCode: 1,
			message:  fmt.Sprintf("Invalid zip file error - the selected file in the archive is not encrypted (file_number:%d file_name:%s)\n", fileNumber, file.Name),
		}
	}

	offset, err := file.DataOffset()
	if err != nil {
		return nil, &cliError{exitCode: 1, message: "Invalid zip file error - invalid Zip archive: " + err.Error() + "\n"}
	}

	input, err := os.Open(path)
	if err != nil {
		return nil, &cliError{exitCode: 1, message: "CLI argument error - \"'inputFile' does not exist\"\n"}
	}
	defer input.Close()

	rawData := make([]byte, file.CompressedSize64)
	section := io.NewSectionReader(input, offset, int64(file.CompressedSize64))
	if _, err := io.ReadFull(section, rawData); err != nil {
		return nil, &cliError{exitCode: 1, message: "Invalid zip file error - invalid Zip archive: " + err.Error() + "\n"}
	}

	target := &encryptedTarget{
		name:             file.Name,
		flags:            file.Flags,
		modifiedTime:     file.ModifiedTime,
		uncompressedSize: file.UncompressedSize64,
		crc32:            file.CRC32,
		rawData:          rawData,
	}

	if file.Method == 99 {
		info, parseErr := parseAESExtra(file.Extra)
		if parseErr != nil {
			return nil, &cliError{exitCode: 1, message: "Invalid zip file error - " + parseErr.Error() + "\n"}
		}
		target.encryption = encryptionAES
		target.method = info.actualMethod
		target.aes = info
		return target, nil
	}

	target.encryption = encryptionZipCrypto
	target.method = file.Method
	return target, nil
}

func openZipReader(path string) (*zip.ReadCloser, error) {
	reader, err := zip.OpenReader(path)
	if err == nil {
		return reader, nil
	}
	hasEOCD, probeErr := fileHasEOCD(path)
	if probeErr == nil && !hasEOCD {
		return nil, fmt.Errorf("invalid Zip archive: Could not find EOCD")
	}
	return nil, fmt.Errorf("invalid Zip archive: %s", err.Error())
}

func fileHasEOCD(path string) (bool, error) {
	file, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer file.Close()

	info, err := file.Stat()
	if err != nil {
		return false, err
	}

	const maxEOCDSearch = 22 + 65535
	size := info.Size()
	searchSize := size
	if searchSize > maxEOCDSearch {
		searchSize = maxEOCDSearch
	}

	buf := make([]byte, searchSize)
	if _, err := file.ReadAt(buf, size-searchSize); err != nil && err != io.EOF {
		return false, err
	}
	for i := len(buf) - 4; i >= 0; i-- {
		if binary.LittleEndian.Uint32(buf[i:i+4]) == 0x06054b50 {
			return true, nil
		}
	}
	return false, nil
}

func parseAESExtra(extra []byte) (*aesInfo, error) {
	for len(extra) >= 4 {
		headerID := binary.LittleEndian.Uint16(extra[:2])
		dataSize := int(binary.LittleEndian.Uint16(extra[2:4]))
		extra = extra[4:]
		if len(extra) < dataSize {
			return nil, fmt.Errorf("invalid Zip archive: truncated extra field")
		}
		data := extra[:dataSize]
		extra = extra[dataSize:]
		if headerID != 0x9901 {
			continue
		}
		if len(data) < 7 {
			return nil, fmt.Errorf("invalid Zip archive: invalid AES extra field")
		}
		info := &aesInfo{
			version:      binary.LittleEndian.Uint16(data[:2]),
			strength:     data[4],
			actualMethod: binary.LittleEndian.Uint16(data[5:7]),
		}
		switch info.strength {
		case 1:
			info.keyLength = 16
			info.saltLength = 8
			info.label = "AES128"
		case 2:
			info.keyLength = 24
			info.saltLength = 12
			info.label = "AES192"
		case 3:
			info.keyLength = 32
			info.saltLength = 16
			info.label = "AES256"
		default:
			return nil, fmt.Errorf("invalid Zip archive: unsupported AES strength")
		}
		return info, nil
	}
	return nil, fmt.Errorf("invalid Zip archive: missing AES metadata")
}

func (target *encryptedTarget) testPassword(password []byte) bool {
	switch target.encryption {
	case encryptionZipCrypto:
		return target.testZipCrypto(password)
	case encryptionAES:
		return target.testAES(password)
	default:
		return false
	}
}

func (target *encryptedTarget) testZipCrypto(password []byte) bool {
	if len(target.rawData) < 12 {
		return false
	}
	state := newZipCryptoState(password)
	header := target.rawData[:12]
	var lastPlain byte
	for _, value := range header {
		lastPlain = state.decryptByte(value)
	}

	checkByte := byte(target.crc32 >> 24)
	if target.flags&0x8 != 0 {
		checkByte = byte(target.modifiedTime >> 8)
	}
	if lastPlain != checkByte {
		return false
	}

	plaintext := make([]byte, len(target.rawData)-12)
	for i, value := range target.rawData[12:] {
		plaintext[i] = state.decryptByte(value)
	}
	return target.verifyData(plaintext, true)
}

func (target *encryptedTarget) testAES(password []byte) bool {
	if target.aes == nil {
		return false
	}
	minSize := target.aes.saltLength + 2 + 10
	if len(target.rawData) < minSize {
		return false
	}

	salt := target.rawData[:target.aes.saltLength]
	passwordVerifier := target.rawData[target.aes.saltLength : target.aes.saltLength+2]
	authCode := target.rawData[len(target.rawData)-10:]
	encrypted := target.rawData[target.aes.saltLength+2 : len(target.rawData)-10]

	derived := pbkdf2SHA1(password, salt, 1000, 2*target.aes.keyLength+2)
	if !bytes.Equal(passwordVerifier, derived[2*target.aes.keyLength:]) {
		return false
	}

	authKey := derived[target.aes.keyLength : 2*target.aes.keyLength]
	mac := hmac.New(sha1.New, authKey)
	_, _ = mac.Write(encrypted)
	if !hmac.Equal(authCode, mac.Sum(nil)[:10]) {
		return false
	}

	block, err := aes.NewCipher(derived[:target.aes.keyLength])
	if err != nil {
		return false
	}

	plaintext := make([]byte, len(encrypted))
	applyWinZipCTR(block, plaintext, encrypted)

	verifyCRC := target.aes.version == 1 || target.crc32 != 0
	return target.verifyData(plaintext, verifyCRC)
}

func (target *encryptedTarget) verifyData(data []byte, verifyCRC bool) bool {
	reader, err := target.compressedReader(data)
	if err != nil {
		return false
	}
	defer reader.Close()

	hash := crc32.NewIEEE()
	written, err := io.Copy(hash, reader)
	if err != nil {
		return false
	}
	if uint64(written) != target.uncompressedSize {
		return false
	}
	if verifyCRC && hash.Sum32() != target.crc32 {
		return false
	}
	return true
}

func (target *encryptedTarget) compressedReader(data []byte) (io.ReadCloser, error) {
	switch target.method {
	case zip.Store:
		return io.NopCloser(bytes.NewReader(data)), nil
	case zip.Deflate:
		return flate.NewReader(bytes.NewReader(data)), nil
	default:
		return nil, fmt.Errorf("unsupported compression method")
	}
}

type zipCryptoState struct {
	keys [3]uint32
}

func newZipCryptoState(password []byte) *zipCryptoState {
	state := &zipCryptoState{
		keys: [3]uint32{0x12345678, 0x23456789, 0x34567890},
	}
	for _, b := range password {
		state.updateKeys(b)
	}
	return state
}

func (state *zipCryptoState) decryptByte(value byte) byte {
	plain := value ^ state.streamByte()
	state.updateKeys(plain)
	return plain
}

func (state *zipCryptoState) streamByte() byte {
	temp := state.keys[2] | 2
	return byte(((temp * (temp ^ 1)) >> 8) & 0xff)
}

func (state *zipCryptoState) updateKeys(value byte) {
	state.keys[0] = crc32UpdateByte(state.keys[0], value)
	state.keys[1] = (state.keys[1] + uint32(state.keys[0]&0xff))*134775813 + 1
	state.keys[2] = crc32UpdateByte(state.keys[2], byte(state.keys[1]>>24))
}

func crc32UpdateByte(current uint32, value byte) uint32 {
	return crc32.IEEETable[byte(current)^value] ^ (current >> 8)
}

func pbkdf2SHA1(password, salt []byte, iterations, keyLength int) []byte {
	const hashLength = sha1.Size
	blocks := (keyLength + hashLength - 1) / hashLength
	output := make([]byte, 0, blocks*hashLength)
	var blockIndex [4]byte

	for block := 1; block <= blocks; block++ {
		binary.BigEndian.PutUint32(blockIndex[:], uint32(block))

		mac := hmac.New(sha1.New, password)
		_, _ = mac.Write(salt)
		_, _ = mac.Write(blockIndex[:])
		u := mac.Sum(nil)
		t := append([]byte(nil), u...)

		for i := 1; i < iterations; i++ {
			mac = hmac.New(sha1.New, password)
			_, _ = mac.Write(u)
			u = mac.Sum(nil)
			for j := range t {
				t[j] ^= u[j]
			}
		}
		output = append(output, t...)
	}

	return output[:keyLength]
}

func applyWinZipCTR(block cipher.Block, dst, src []byte) {
	counter := make([]byte, aes.BlockSize)
	keystream := make([]byte, aes.BlockSize)
	counter[0] = 1

	for len(src) > 0 {
		block.Encrypt(keystream, counter)
		n := len(src)
		if n > aes.BlockSize {
			n = aes.BlockSize
		}
		for i := 0; i < n; i++ {
			dst[i] = src[i] ^ keystream[i]
		}
		incrementLittleEndian(counter)
		dst = dst[n:]
		src = src[n:]
	}
}

func incrementLittleEndian(counter []byte) {
	for i := 0; i < len(counter); i++ {
		counter[i]++
		if counter[i] != 0 {
			return
		}
	}
}

