   348	func validateRunConfig(cfg config) (runConfig, *cliError) {
   349		if !pathExists(cfg.inputFile) {
   350			return runConfig{}, runtimeArgError("'inputFile' does not exist")
   351		}
   352		if cfg.passwordDictionary != "" && !pathExists(cfg.passwordDictionary) {
   353			return runConfig{}, runtimeArgError("'passwordDictionary' does not exist")
   354		}
   355		if cfg.charsetFile != "" && !pathExists(cfg.charsetFile) {
   356			return runConfig{}, runtimeArgError("'charsetFile' does not exist")
   357		}
   358		if cfg.workers <= 0 {
   359			return runConfig{}, runtimeArgError("'workers' must be positive")
   360		}
   361		if cfg.maxPasswordLen < cfg.minPasswordLen {
   362			return runConfig{}, runtimeArgError("'maxPasswordLen' must be equal or greater than 'minPasswordLen'")
   363		}
   364		if cfg.passwordDictionary != "" && cfg.startingPassword != "" {
   365			return runConfig{}, runtimeArgError("'startingPassword' cannot be used with a dictionary file")
   366		}
   367	
   368		runCfg := runConfig{cfg: cfg}
   369		if cfg.passwordDictionary != "" {
   370			dict, err := loadDictionary(cfg.passwordDictionary)
   371			if err != nil {
   372				return runConfig{}, err
   373			}
   374			runCfg.dict = dict
   375			return runCfg, nil
   376		}
   377	
   378		var charset []byte
   379		var err *cliError
   380		if cfg.charsetFile != "" {
   381			charset, err = loadCharsetFile(cfg.charsetFile)
   382		} else {
   383			charset, err = buildCharsetFromSpec(cfg.charsetSpec)
   384		}
   385		if err != nil {
   386			return runConfig{}, err
   387		}
   388	
   389		if cfg.startingPassword != "" {
   390			passwordBytes := []byte(cfg.startingPassword)
   391			if len(passwordBytes) < cfg.minPasswordLen || len(passwordBytes) > cfg.maxPasswordLen {
   392				return runConfig{}, runtimeArgError("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration")
   393			}
   394			if !charsetContainsAll(charset, passwordBytes) {
   395				return runConfig{}, runtimeArgError("'startingPassword' uses characters out of the generation charset")
   396			}
   397		}
   398	
   399		runCfg.charset = charset
   400		return runCfg, nil
   401	}
