   403	func loadDictionary(path string) ([][]byte, *cliError) {
   404		file, err := os.Open(path)
   405		if err != nil {
   406			return nil, runtimeArgError("'passwordDictionary' does not exist")
   407		}
   408		defer file.Close()
   409	
   410		scanner := bufio.NewScanner(file)
   411		passwords := make([][]byte, 0)
   412		for scanner.Scan() {
   413			line := append([]byte(nil), scanner.Bytes()...)
   414			passwords = append(passwords, line)
   415		}
   416		if err := scanner.Err(); err != nil {
   417			return nil, &cliError{exitCode: 1, message: "Dictionary file error - " + err.Error() + "\n"}
   418		}
   419		return passwords, nil
   420	}
   421	
   422	func loadCharsetFile(path string) ([]byte, *cliError) {
   423		data, err := os.ReadFile(path)
   424		if err != nil {
   425			return nil, runtimeArgError("'charsetFile' does not exist")
   426		}
   427		return uniqueSortedBytes(data), nil
   428	}
   429	
   430	func buildCharsetFromSpec(spec string) ([]byte, *cliError) {
   431		set := make([]byte, 0, 64)
   432		for i := 0; i < len(spec); i++ {
   433			chars, ok := charsetClasses[spec[i]]
   434			if !ok {
   435				return nil, runtimeQuotedError(fmt.Sprintf("Unknown charset option '%c'", spec[i]))
   436			}
   437			set = append(set, chars...)
   438		}
   439		return uniqueSortedBytes(set), nil
   440	}
   441	
   442	func charsetContainsAll(charset, value []byte) bool {
   443		if len(value) == 0 {
   444			return true
   445		}
   446		var table [256]bool
   447		for _, b := range charset {
   448			table[b] = true
   449		}
   450		for _, b := range value {
   451			if !table[b] {
   452				return false
   453			}
   454		}
   455		return true
   456	}
   457	
   458	func uniqueSortedBytes(src []byte) []byte {
   459		if len(src) == 0 {
   460			return nil
   461		}
   462		seen := [256]bool{}
   463		dst := make([]byte, 0, len(src))
   464		for _, b := range src {
   465			if !seen[b] {
   466				seen[b] = true
   467				dst = append(dst, b)
   468			}
   469		}
   470		sort.Slice(dst, func(i, j int) bool { return dst[i] < dst[j] })
   471		return dst
   472	}
   473	
   474	func searchDictionary(target *encryptedTarget, dict [][]byte, workers int) (bool, []byte) {
   475		if len(dict) == 0 {
   476			return false, nil
   477		}
   478	
   479		var (
   480			found  atomic.Bool
   481			result atomic.Value
   482			wg     sync.WaitGroup
   483		)
   484	
   485		for worker := 0; worker < workers; worker++ {
   486			start := len(dict) * worker / workers
   487			end := len(dict) * (worker + 1) / workers
   488			if start >= end {
   489				continue
   490			}
   491			wg.Add(1)
   492			go func(start, end int) {
   493				defer wg.Done()
   494				for i := start; i < end; i++ {
   495					if found.Load() {
   496						return
   497					}
   498					if target.testPassword(dict[i]) {
   499						if !found.Swap(true) {
   500							result.Store(append([]byte(nil), dict[i]...))
   501						}
   502						return
   503					}
   504				}
   505			}(start, end)
   506		}
   507	
   508		wg.Wait()
   509		if !found.Load() {
   510			return false, nil
   511		}
   512		return true, result.Load().([]byte)
   513	}
   514	
   515	func searchBruteForce(target *encryptedTarget, charset []byte, minLen, maxLen int, startingPassword []byte, workers int) (bool, []byte) {
   516		if len(charset) == 0 {
   517			return false, nil
   518		}
   519	
   520		indexMap := make(map[byte]int, len(charset))
   521		for i, b := range charset {
   522			indexMap[b] = i
   523		}
   524	
   525		var (
   526			found  atomic.Bool
   527			result atomic.Value
   528		)
   529	
   530		for length := minLen; length <= maxLen && !found.Load(); length++ {
   531			if len(startingPassword) > 0 && length < len(startingPassword) {
   532				continue
   533			}
   534	
   535			total, ok := powUint64(uint64(len(charset)), length)
   536			if !ok {
   537				total = math.MaxUint64
   538			}
   539	
   540			startIndex := uint64(0)
   541			if len(startingPassword) > 0 && length == len(startingPassword) {
   542				startIndex = passwordIndex(startingPassword, indexMap, len(charset))
   543			}
   544			if startIndex >= total {
   545				continue
   546			}
   547	
   548			remaining := total - startIndex
   549			if remaining == 0 {
   550				continue
   551			}
   552	
   553			var wg sync.WaitGroup
   554			for worker := 0; worker < workers; worker++ {
   555				begin := startIndex + remaining*uint64(worker)/uint64(workers)
   556				end := startIndex + remaining*uint64(worker+1)/uint64(workers)
   557				if begin >= end {
   558					continue
   559				}
   560				wg.Add(1)
   561				go func(length int, begin, end uint64) {
   562					defer wg.Done()
   563					digits := indexToDigits(begin, length, len(charset))
   564					candidate := digitsToPassword(digits, charset)
   565					for current := begin; current < end; current++ {
   566						if found.Load() {
   567							return
   568						}
   569						if target.testPassword(candidate) {
   570							if !found.Swap(true) {
   571								result.Store(append([]byte(nil), candidate...))
   572							}
   573							return
   574						}
   575						if current+1 >= end {
   576							return
   577						}
   578						incrementPassword(digits, candidate, charset)
   579					}
   580				}(length, begin, end)
   581			}
   582			wg.Wait()
   583		}
   584	
   585		if !found.Load() {
   586			return false, nil
   587		}
   588		return true, result.Load().([]byte)
   589	}
   590	
   591	func passwordIndex(password []byte, indexMap map[byte]int, base int) uint64 {
   592		var idx uint64
   593		for _, b := range password {
   594			idx = idx*uint64(base) + uint64(indexMap[b])
   595		}
   596		return idx
   597	}
   598	
   599	func indexToDigits(index uint64, length, base int) []int {
   600		digits := make([]int, length)
   601		for i := length - 1; i >= 0; i-- {
   602			digits[i] = int(index % uint64(base))
   603			index /= uint64(base)
   604		}
   605		return digits
   606	}
   607	
   608	func digitsToPassword(digits []int, charset []byte) []byte {
   609		password := make([]byte, len(digits))
   610		for i, digit := range digits {
   611			password[i] = charset[digit]
   612		}
   613		return password
   614	}
   615	
   616	func incrementPassword(digits []int, password, charset []byte) {
   617		for i := len(digits) - 1; i >= 0; i-- {
   618			digits[i]++
   619			if digits[i] < len(charset) {
   620				password[i] = charset[digits[i]]
   621				for j := i + 1; j < len(digits); j++ {
   622					digits[j] = 0
   623					password[j] = charset[0]
   624				}
   625				return
   626			}
   627			digits[i] = 0
   628			password[i] = charset[0]
   629		}
   630	}
   631	
   632	func powUint64(base uint64, exp int) (uint64, bool) {
   633		if exp == 0 {
   634			return 1, true
   635		}
   636		value := uint64(1)
   637		for i := 0; i < exp; i++ {
   638			if base != 0 && value > math.MaxUint64/base {
   639				return 0, false
   640			}
   641			value *= base
   642		}
   643		return value, true
   644	}
