   646	func printTTYPrelude(target *encryptedTarget, runCfg runConfig) {
   647		writeStdout(fmt.Sprintf("Targeting file '%s' within the archive\n", target.name))
   648		switch target.encryption {
   649		case encryptionZipCrypto:
   650			writeStdout("Archive encrypted with ZipCrypto - expect a much faster throughput\n")
   651		case encryptionAES:
   652			writeStdout(fmt.Sprintf("Archive encrypted with %s - expect a long wait time\n", target.aes.label))
   653		}
   654		if len(runCfg.dict) > 0 {
   655			writeStdout(fmt.Sprintf("Using passwords dictionary %q with %d candidates.\n", runCfg.cfg.passwordDictionary, len(runCfg.dict)))
   656		}
   657		writeStdout(fmt.Sprintf("Starting %d workers to test passwords\n", runCfg.cfg.workers))
   658		if len(runCfg.dict) == 0 {
   659			if runCfg.cfg.startingPassword != "" {
   660				writeStdout(fmt.Sprintf(
   661					"Generating passwords with length from %d to %d starting from %s for charset with length %d\n",
   662					runCfg.cfg.minPasswordLen,
   663					runCfg.cfg.maxPasswordLen,
   664					runCfg.cfg.startingPassword,
   665					len(runCfg.charset),
   666				))
   667			} else {
   668				writeStdout(fmt.Sprintf(
   669					"Generating passwords with length from %d to %d for charset with length %d\n",
   670					runCfg.cfg.minPasswordLen,
   671					runCfg.cfg.maxPasswordLen,
   672					len(runCfg.charset),
   673				))
   674			}
   675			if len(runCfg.charset) > 0 {
   676				writeStdout(string(runCfg.charset) + "\n")
   677			}
   678		}
   679	}
