   681	func parseUintArg(value string) (uint64, string) {
   682		if value == "" {
   683			return 0, "cannot parse integer from empty string"
   684		}
   685		for i := 0; i < len(value); i++ {
   686			if value[i] < '0' || value[i] > '9' {
   687				return 0, "invalid digit found in string"
   688			}
   689		}
   690		n := new(big.Int)
   691		if _, ok := n.SetString(value, 10); !ok {
   692			return 0, "invalid digit found in string"
   693		}
   694		if n.BitLen() > 64 {
   695			return 0, "number too large to fit in target type"
   696		}
   697		return n.Uint64(), ""
   698	}
