   707	func longOptionValue(args []string, index *int, name, inlineValue string, hasInlineValue bool) (string, *cliError) {
   708		if hasInlineValue {
   709			return inlineValue, nil
   710		}
   711		if *index+1 >= len(args) {
   712			return "", missingValueError(optionDisplays[canonicalNameForLong(name)])
   713		}
   714		next := args[*index+1]
   715		if strings.HasPrefix(next, "-") && next != "-" {
   716			if isKnownOptionToken(next) {
   717				return "", missingValueError(optionDisplays[canonicalNameForLong(name)])
   718			}
   719			return "", unexpectedArgumentError(next)
   720		}
   721		*index++
   722		return next, nil
   723	}
   724	
   725	func shortOptionValue(args []string, index *int, cluster string, clusterIndex *int, short byte) (string, *cliError) {
   726		if *clusterIndex+1 < len(cluster) {
   727			value := cluster[*clusterIndex+1:]
   728			*clusterIndex = len(cluster)
   729			return value, nil
   730		}
   731		if *index+1 >= len(args) {
   732			return "", missingValueError(optionDisplays[canonicalNameForShort(short)])
   733		}
   734		next := args[*index+1]
   735		if strings.HasPrefix(next, "-") && next != "-" {
   736			if isKnownOptionToken(next) {
   737				return "", missingValueError(optionDisplays[canonicalNameForShort(short)])
   738			}
   739			return "", unexpectedArgumentError(next)
   740		}
   741		*index++
   742		*clusterIndex = len(cluster)
   743		return next, nil
   744	}
   745	
   746	func isKnownOptionToken(token string) bool {
   747		if token == "" {
   748			return false
   749		}
   750		if strings.HasPrefix(token, "--") {
   751			name, _, _ := splitLongOption(token)
   752			switch name {
   753			case "--inputFile", "--workers", "--passwordDictionary", "--charset", "--charsetFile", "--minPasswordLen", "--maxPasswordLen", "--fileNumber", "--startingPassword", "--help", "--version":
   754				return true
   755			default:
   756				return false
